import { GoogleGenAI, Type } from "@google/genai";
import { Brand, Campaign, BrandTone } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async generateCampaignCopy(brand: Brand, campaign: Campaign) {
    if (!process.env.API_KEY) {
      return this.fallbackCopy(brand, campaign);
    }

    try {
      const prompt = `
        Generate marketing copy for a campaign.
        Brand: ${brand.name} (${brand.description})
        Tone: ${brand.tone}
        Offer: ${campaign.offer}
        Objective: ${campaign.objective}

        Requirements:
        1. 15 short headlines (max 30 chars)
        2. 5 long headlines (max 90 chars)
        3. 5 short descriptions (max 60 chars)
        4. 5 long descriptions (max 90 chars)
        5. 3 Call to Action variants (max 20 chars)
      `;

      const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              shortHeadlines: { type: Type.ARRAY, items: { type: Type.STRING } },
              longHeadlines: { type: Type.ARRAY, items: { type: Type.STRING } },
              shortDescriptions: { type: Type.ARRAY, items: { type: Type.STRING } },
              longDescriptions: { type: Type.ARRAY, items: { type: Type.STRING } },
              ctas: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ["shortHeadlines", "longHeadlines", "shortDescriptions", "longDescriptions", "ctas"]
          }
        }
      });

      return JSON.parse(response.text);
    } catch (error) {
      console.error("Gemini failed, using fallback", error);
      return this.fallbackCopy(brand, campaign);
    }
  }

  private fallbackCopy(brand: Brand, campaign: Campaign) {
    const truncate = (str: string, max: number) => 
      str.length > max ? str.substring(0, max - 3) + '...' : str;

    const baseHeadline = `${campaign.offer} at ${brand.name}`;
    const baseDesc = `Get the best deals on ${brand.industry} for our ${campaign.market} customers. ${campaign.objective === 'Sales' ? 'Shop now!' : 'Learn more.'}`;

    return {
      shortHeadlines: Array(15).fill(0).map((_, i) => truncate(`${campaign.offer} - ${brand.name} #${i + 1}`, 30)),
      longHeadlines: Array(5).fill(0).map((_, i) => truncate(`${baseHeadline}: Exclusive ${brand.tone} Collection Available Now!`, 90)),
      shortDescriptions: Array(5).fill(0).map((_, i) => truncate(`Premium ${brand.industry} products. ${campaign.offer} for a limited time.`, 60)),
      longDescriptions: Array(5).fill(0).map((_, i) => truncate(`${baseDesc} Experience the luxury of ${brand.name} with our ${brand.tone} selection.`, 90)),
      ctas: ["Shop Now", "Buy Now", "Claim Offer"]
    };
  }
}

export const geminiService = new GeminiService();

import React, { useState, useEffect, createContext, useContext } from 'react';
import { Brand, Product, Campaign, CampaignObjective, BrandTone } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import BrandWizard from './components/BrandWizard';
import ProductManager from './components/ProductManager';
import CampaignManager from './components/CampaignManager';
import Editor from './components/Editor';
import FeedManager from './components/FeedManager';
import PublishManager from './components/PublishManager';
import { geminiService } from './services/geminiService';

// --- Context & Persistence ---
interface AppState {
  brands: Brand[];
  products: Product[];
  campaigns: Campaign[];
  activeBrandId?: string;
  addBrand: (brand: Brand) => void;
  addProduct: (product: Product) => void;
  addCampaign: (campaign: Campaign) => void;
  updateCampaign: (campaign: Campaign) => void;
}

const AppContext = createContext<AppState | undefined>(undefined);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

// --- Main App Component ---
const App: React.FC = () => {
  const [brands, setBrands] = useState<Brand[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [activeBrandId, setActiveBrandId] = useState<string>();
  const [view, setView] = useState('dashboard');
  const [editingAssetId, setEditingAssetId] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('designoir_state');
    if (saved) {
      const parsed = JSON.parse(saved);
      setBrands(parsed.brands || []);
      setProducts(parsed.products || []);
      setCampaigns(parsed.campaigns || []);
      if (parsed.brands?.length > 0) setActiveBrandId(parsed.brands[0].id);
    } else {
      // Seed Data
      const demoBrand: Brand = {
        id: 'b1',
        name: 'Noir Luxe',
        description: 'High-end sustainable fashion',
        industry: 'Fashion',
        targetAudience: 'Professionals 25-45',
        tone: BrandTone.LUXURY,
        platforms: ['Instagram', 'Shopify Website', 'Google PMAX'],
        kit: { primaryColor: '#000000', secondaryColor: '#d4af37', fontFamily: 'Inter' }
      };
      setBrands([demoBrand]);
      setActiveBrandId(demoBrand.id);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('designoir_state', JSON.stringify({ brands, products, campaigns }));
  }, [brands, products, campaigns]);

  const addBrand = (b: Brand) => { setBrands(prev => [...prev, b]); setActiveBrandId(b.id); };
  const addProduct = (p: Product) => setProducts(prev => [...prev, p]);
  const addCampaign = (c: Campaign) => setCampaigns(prev => [...prev, c]);
  const updateCampaign = (c: Campaign) => setCampaigns(prev => prev.map(item => item.id === c.id ? c : item));

  const state: AppState = { brands, products, campaigns, activeBrandId, addBrand, addProduct, addCampaign, updateCampaign };

  const renderView = () => {
    if (editingAssetId) {
      return <Editor assetId={editingAssetId} onClose={() => setEditingAssetId(null)} />;
    }

    switch (view) {
      case 'dashboard': return <Dashboard setView={setView} />;
      case 'brands': return <BrandWizard onComplete={() => setView('dashboard')} />;
      case 'products': return <ProductManager />;
      case 'campaigns': return <CampaignManager onEditAsset={(id) => setEditingAssetId(id)} />;
      case 'feeds': return <FeedManager />;
      case 'publish': return <PublishManager />;
      default: return <Dashboard setView={setView} />;
    }
  };

  return (
    <AppContext.Provider value={state}>
      <div className="flex min-h-screen bg-slate-50">
        <Sidebar activeView={view} setView={setView} />
        <main className="flex-1 p-8 overflow-y-auto">
          {renderView()}
        </main>
      </div>
    </AppContext.Provider>
  );
};

export default App;

