const CampaignManager: React.FC<{ onEditAsset: (id: string) => void }> = ({ onEditAsset }) => {
  const { campaigns, products, activeBrandId, brands, addCampaign, updateCampaign } = useApp();
  const [showWizard, setShowWizard] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [newCamp, setNewCamp] = useState<Partial<Campaign>>({
    name: '',
    offer: '',
    cta: 'Shop Now',
    objective: CampaignObjective.SALES,
    market: 'International',
    productIds: []
  });

  const activeBrand = brands.find(b => b.id === activeBrandId);

  const startGeneration = async (campaignId: string) => {
    const camp = campaigns.find(c => c.id === campaignId);
    if (!camp || !activeBrand) return;

    setIsGenerating(true);
    updateCampaign({ ...camp, status: 'Generating' });

    // 1. Generate Copy using Gemini
    const copy = await geminiService.generateCampaignCopy(activeBrand, camp);

    // 2. Map Assets based on platforms
    const generatedAssets: CampaignAsset[] = [];
    activeBrand.platforms.forEach(platform => {
      const sizes = ASSET_SIZES[platform] || [];
      sizes.forEach((size, idx) => {
        // Create 3 variations for each size
        for (let v = 1; v <= 3; v++) {
          generatedAssets.push({
            id: `asset-${campaignId}-${platform}-${idx}-${v}`,
            name: `${size.name} V${v}`,
            size: { width: size.width, height: size.height },
            category: size.category,
            variation: v,
            // Simulated render
            dataUrl: 'https://picsum.photos/seed/' + Math.random() + '/' + size.width + '/' + size.height
          });
        }
      });
    });

    updateCampaign({ 
      ...camp, 
      status: 'Ready', 
      assets: generatedAssets,
      pmaxText: {
        headlines: copy.shortHeadlines,
        longHeadlines: copy.longHeadlines,
        descriptions: copy.longDescriptions,
        shortDescriptions: copy.shortDescriptions
      }
    });

    setIsGenerating(false);
  };

  const handleCreate = () => {
    if (!activeBrandId) return;
    const c: Campaign = {
      id: `c-${Date.now()}`,
      brandId: activeBrandId,
      name: newCamp.name || 'Summer Collection',
      offer: newCamp.offer || '20% OFF',
      cta: newCamp.cta || 'Shop Now',
      objective: newCamp.objective || CampaignObjective.SALES,
      market: newCamp.market || 'UK',
      productIds: newCamp.productIds || [],
      status: 'Draft',
      assets: []
    };
    addCampaign(c);
    setShowWizard(false);
  };

  return (
    <div className="max-w-6xl mx-auto">
      <header className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-2xl font-bold">Campaigns</h2>
          <p className="text-slate-500 text-sm">Create and manage your bulk marketing assets</p>
        </div>
        <button 
          onClick={() => setShowWizard(true)}
          className="bg-black text-white px-4 py-2 rounded-lg text-sm font-semibold"
        >
          New Campaign
        </button>
      </header>

      {showWizard && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl p-8 max-w-lg w-full">
            <h3 className="text-xl font-bold mb-6">Create Campaign</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Campaign Name</label>
                <input 
                  type="text" className="w-full p-2.5 border rounded-lg"
                  value={newCamp.name}
                  onChange={e => setNewCamp({...newCamp, name: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Core Offer</label>
                <input 
                  type="text" className="w-full p-2.5 border rounded-lg" placeholder="e.g. End of Season - 30% OFF"
                  value={newCamp.offer}
                  onChange={e => setNewCamp({...newCamp, offer: e.target.value})}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Primary CTA</label>
                  <input 
                    type="text" className="w-full p-2.5 border rounded-lg"
                    value={newCamp.cta}
                    onChange={e => setNewCamp({...newCamp, cta: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Objective</label>
                  <select 
                    className="w-full p-2.5 border rounded-lg"
                    value={newCamp.objective}
                    onChange={e => setNewCamp({...newCamp, objective: e.target.value as CampaignObjective})}
                  >
                    {Object.values(CampaignObjective).map(o => <option key={o} value={o}>{o}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">Select Products</label>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto p-2 border rounded-lg">
                  {products.map(p => (
                    <label key={p.id} className="flex items-center gap-2 text-xs">
                      <input 
                        type="checkbox" 
                        checked={newCamp.productIds?.includes(p.id)}
                        onChange={(e) => {
                          const ids = newCamp.productIds || [];
                          setNewCamp({...newCamp, productIds: e.target.checked ? [...ids, p.id] : ids.filter(id => id !== p.id)});
                        }}
                      />
                      {p.name}
                    </label>
                  ))}
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-8">
              <button onClick={() => setShowWizard(false)} className="flex-1 px-4 py-2 border rounded-lg font-semibold">Cancel</button>
              <button onClick={handleCreate} className="flex-1 px-4 py-2 bg-black text-white rounded-lg font-semibold">Create Draft</button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-8">
        {campaigns.map(c => (
          <div key={c.id} className="bg-white border rounded-2xl overflow-hidden shadow-sm">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <div>
                <h3 className="text-lg font-bold">{c.name}</h3>
                <p className="text-sm text-slate-500">{c.offer} • {c.objective}</p>
              </div>
              <div className="flex items-center gap-3">
                {c.status === 'Draft' && (
                  <button 
                    onClick={() => startGeneration(c.id)}
                    disabled={isGenerating}
                    className="bg-black text-white px-4 py-2 rounded-lg text-sm font-semibold disabled:bg-slate-500"
                  >
                    {isGenerating ? 'Generating Assets...' : 'Generate Assets'}
                  </button>
                )}
                {c.status === 'Ready' && (
                  <button className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-semibold">
                    Download All (ZIP)
                  </button>
                )}
                <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                  c.status === 'Ready' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'
                }`}>
                  {c.status}
                </span>
              </div>
            </div>

            <div className="p-6">
              {c.assets.length === 0 ? (
                <div className="text-center py-12 text-slate-400">
                  {c.status === 'Generating' ? 'AI is creating your assets... please wait.' : 'Assets not yet generated.'}
                </div>
              ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-4">
                  {c.assets.slice(0, 12).map(a => (
                    <div key={a.id} className="group relative">
                      <div className="aspect-square bg-slate-100 rounded-lg overflow-hidden border">
                        <img src={a.dataUrl} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2">
                          <button 
                            onClick={() => onEditAsset(a.id)}
                            className="bg-white text-black text-[10px] font-bold px-3 py-1 rounded shadow"
                          >
                            EDIT
                          </button>
                          <span className="text-[10px] text-white text-center px-2">{a.name}</span>
                        </div>
                      </div>
                    </div>
                  ))}
                  {c.assets.length > 12 && (
                    <div className="aspect-square bg-slate-50 border rounded-lg flex items-center justify-center text-slate-400 font-bold text-sm">
                      +{c.assets.length - 12} more
                    </div>
                  )}
                </div>
              )}
            </div>

            {c.pmaxText && (
              <div className="p-6 border-t bg-slate-50">
                <h4 className="font-bold text-sm mb-4">Google PMAX Text Bundle</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="bg-white p-4 border rounded-xl text-xs">
                    <p className="font-bold mb-2">Headlines (Short)</p>
                    <ul className="space-y-1 list-disc pl-4 text-slate-600">
                      {c.pmaxText.headlines.slice(0, 5).map((h, i) => <li key={i}>{h}</li>)}
                    </ul>
                  </div>
                  <div className="bg-white p-4 border rounded-xl text-xs">
                    <p className="font-bold mb-2">Descriptions</p>
                    <ul className="space-y-1 list-disc pl-4 text-slate-600">
                      {c.pmaxText.descriptions.slice(0, 5).map((d, i) => <li key={i}>{d}</li>)}
                    </ul>
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default CampaignManager;

import React, { useEffect, useRef, useState } from 'react';
import { useApp } from '../App';

interface EditorProps {
  assetId: string;
  onClose: () => void;
}

const Editor: React.FC<EditorProps> = ({ assetId, onClose }) => {
  const { campaigns, updateCampaign } = useApp();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fabricCanvas = useRef<any>(null);
  const [activeObject, setActiveObject] = useState<any>(null);

  const campaign = campaigns.find(c => c.assets.some(a => a.id === assetId));
  const asset = campaign?.assets.find(a => a.id === assetId);

  useEffect(() => {
    if (!canvasRef.current || !asset) return;

    // Initialize fabric
    fabricCanvas.current = new fabric.Canvas(canvasRef.current, {
      backgroundColor: '#ffffff',
      width: asset.size.width > 800 ? 800 : asset.size.width,
      height: (asset.size.width > 800 ? 800 : asset.size.width) * (asset.size.height / asset.size.width),
    });

    // Zoom and fit
    const zoom = fabricCanvas.current.width / asset.size.width;
    fabricCanvas.current.setZoom(zoom);

    // Load state if exists or add initial elements
    if (asset.editorState) {
      fabricCanvas.current.loadFromJSON(asset.editorState);
    } else {
      // Add background
      const rect = new fabric.Rect({
        left: 0, top: 0,
        fill: '#f8fafc',
        width: asset.size.width, height: asset.size.height,
        selectable: false
      });
      fabricCanvas.current.add(rect);

      // Add Text
      const text = new fabric.IText(campaign?.offer || 'Your Offer', {
        left: 100, top: 100,
        fontSize: 120,
        fontFamily: 'Inter',
        fontWeight: 'bold',
        fill: '#000000'
      });
      fabricCanvas.current.add(text);

      // Add CTA
      const btn = new fabric.Rect({
        left: 100, top: 300,
        fill: '#000000',
        width: 400, height: 100,
        rx: 10, ry: 10
      });
      const btnText = new fabric.Text(campaign?.cta || 'Shop Now', {
        left: 150, top: 325,
        fill: '#ffffff',
        fontSize: 40,
        fontFamily: 'Inter'
      });
      fabricCanvas.current.add(new fabric.Group([btn, btnText], { left: 100, top: 400 }));
    }

    fabricCanvas.current.on('selection:created', (e: any) => setActiveObject(e.selected[0]));
    fabricCanvas.current.on('selection:updated', (e: any) => setActiveObject(e.selected[0]));
    fabricCanvas.current.on('selection:cleared', () => setActiveObject(null));

    return () => {
      fabricCanvas.current.dispose();
    };
  }, [assetId]);

  const handleSave = () => {
    if (!campaign || !asset || !fabricCanvas.current) return;

    const newState = JSON.stringify(fabricCanvas.current.toJSON());
    const dataUrl = fabricCanvas.current.toDataURL({ format: 'png', multiplier: 1 / fabricCanvas.current.getZoom() });

    const updatedAssets = campaign.assets.map(a => 
      a.id === assetId ? { ...a, editorState: newState, dataUrl } : a
    );

    updateCampaign({ ...campaign, assets: updatedAssets });
    onClose();
  };

  const addText = () => {
    const text = new fabric.IText('Double click to edit', {
      left: 100, top: 100,
      fontSize: 60,
      fontFamily: 'Inter'
    });
    fabricCanvas.current.add(text);
    fabricCanvas.current.setActiveObject(text);
  };

  const changeColor = (color: string) => {
    if (activeObject) {
      activeObject.set('fill', color);
      fabricCanvas.current.renderAll();
    }
  };

  if (!asset) return null;

  return (
    <div className="fixed inset-0 bg-slate-900 z-[60] flex flex-col">
      <nav className="h-16 border-b border-slate-700 bg-slate-800 flex items-center justify-between px-6 text-white">
        <div className="flex items-center gap-4">
          <button onClick={onClose} className="hover:text-slate-300">✕</button>
          <h2 className="font-bold text-sm uppercase tracking-widest">{asset.name} ({asset.size.width}x{asset.size.height})</h2>
        </div>
        <button 
          onClick={handleSave}
          className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-lg font-bold text-sm transition-colors"
        >
          Save Edits
        </button>
      </nav>

      <div className="flex-1 flex overflow-hidden">
        {/* Toolbar */}
        <aside className="w-20 bg-slate-800 border-r border-slate-700 flex flex-col items-center py-6 gap-6 text-white text-xs">
          <button onClick={addText} className="flex flex-col items-center gap-1 hover:bg-slate-700 p-2 rounded w-full">
            <span>T</span>
            Text
          </button>
          <button onClick={() => {
            const rect = new fabric.Rect({ width: 200, height: 200, fill: '#000', left: 100, top: 100 });
            fabricCanvas.current.add(rect);
          }} className="flex flex-col items-center gap-1 hover:bg-slate-700 p-2 rounded w-full">
            <span>⬜</span>
            Shape
          </button>
        </aside>

        {/* Workspace */}
        <div className="flex-1 bg-slate-900 flex items-center justify-center p-12 overflow-auto">
          <div className="bg-white shadow-2xl relative">
            <canvas ref={canvasRef} />
          </div>
        </div>

        {/* Inspector */}
        <aside className="w-64 bg-slate-800 border-l border-slate-700 p-6 text-white">
          <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-6">Inspector</h3>
          {activeObject ? (
            <div className="space-y-6">
              <div>
                <label className="block text-[10px] text-slate-500 mb-2 uppercase font-bold">Fill Color</label>
                <div className="grid grid-cols-4 gap-2">
                  {['#000000', '#ffffff', '#ff0000', '#00ff00', '#0000ff', '#ffff00', '#d4af37', '#7c3aed'].map(c => (
                    <button 
                      key={c}
                      onClick={() => changeColor(c)}
                      className="w-8 h-8 rounded border border-slate-600"
                      style={{ backgroundColor: c }}
                    />
                  ))}
                </div>
              </div>
              {activeObject.text !== undefined && (
                <div>
                  <label className="block text-[10px] text-slate-500 mb-2 uppercase font-bold">Font Size</label>
                  <input 
                    type="range" min="10" max="500" 
                    value={activeObject.fontSize} 
                    onChange={(e) => {
                      activeObject.set('fontSize', parseInt(e.target.value));
                      fabricCanvas.current.renderAll();
                    }}
                    className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                  />
                </div>
              )}
              <button 
                onClick={() => {
                  fabricCanvas.current.remove(activeObject);
                  fabricCanvas.current.discardActiveObject();
                }}
                className="w-full py-2 bg-red-900/30 text-red-400 rounded-lg text-xs font-bold border border-red-900/50"
              >
                Delete Layer
              </button>
            </div>
          ) : (
            <p className="text-slate-500 text-xs italic">Select an element to edit properties.</p>
          )}
        </aside>
      </div>
    </div>
  );
};

export default Editor;

import React, { useState } from 'react';
import { useApp } from '../App';

const FeedManager: React.FC = () => {
  const { products, activeBrandId, brands } = useApp();
  const [feedType, setFeedType] = useState('Awin');

  const brand = brands.find(b => b.id === activeBrandId);

  const generateCSV = () => {
    if (!brand || products.length === 0) return;

    let headers: string[] = [];
    if (feedType === 'Awin') {
      headers = ['product_id', 'product_name', 'description', 'price', 'currency', 'brand', 'category', 'product_url', 'image_url', 'availability'];
    } else if (feedType === 'Webgains') {
      headers = ['ProductID', 'ProductName', 'ProductDescription', 'Price', 'Currency', 'Brand', 'CategoryName', 'ProductURL', 'ImageURL', 'StockStatus'];
    } else {
      headers = ['id', 'name', 'desc', 'price', 'brand', 'url'];
    }

    const rows = products.filter(p => p.brandId === activeBrandId).map(p => {
      if (feedType === 'Awin') {
        return [p.id, p.name, p.description, p.price, 'GBP', brand.name, brand.industry, 'https://example.com/p/' + p.id, p.processedImageUrl, 'in_stock'];
      }
      return [p.id, p.name, p.description, p.price, brand.name, 'https://example.com/p/' + p.id];
    });

    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${brand.name.replace(/\s+/g, '_')}_${feedType}_Feed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="max-w-4xl mx-auto">
      <header className="mb-10">
        <h2 className="text-3xl font-bold text-slate-900">Partner Feeds</h2>
        <p className="text-slate-500 mt-1">Export your product catalog to affiliate networks.</p>
      </header>

      <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
        <div className="max-w-md space-y-6">
          <div>
            <label className="block text-sm font-medium mb-2">Network Protocol</label>
            <div className="grid grid-cols-3 gap-2">
              {['Awin', 'Webgains', 'Generic'].map(f => (
                <button 
                  key={f}
                  onClick={() => setFeedType(f)}
                  className={`py-2 text-xs font-bold rounded-lg border transition-all ${
                    feedType === f ? 'bg-black text-white border-black' : 'bg-white text-slate-600 border-slate-200'
                  }`}
                >
                  {f}
                </button>
              ))}
            </div>
          </div>

          <div className="bg-slate-50 p-4 rounded-xl text-xs space-y-2">
            <p className="font-bold text-slate-700">Mapping Configuration</p>
            <div className="flex justify-between text-slate-500 border-b border-slate-200 pb-2">
              <span>Internal Field</span>
              <span>Network Target</span>
            </div>
            <div className="flex justify-between py-1">
              <span>id</span>
              <span className="text-slate-800">{feedType === 'Webgains' ? 'ProductID' : 'product_id'}</span>
            </div>
            <div className="flex justify-between py-1">
              <span>name</span>
              <span className="text-slate-800">{feedType === 'Webgains' ? 'ProductName' : 'product_name'}</span>
            </div>
            <div className="flex justify-between py-1">
              <span>processedImageUrl</span>
              <span className="text-slate-800">{feedType === 'Webgains' ? 'ImageURL' : 'image_url'}</span>
            </div>
          </div>

          <button 
            onClick={generateCSV}
            className="w-full bg-black text-white py-3 rounded-lg font-bold hover:bg-slate-800 transition-colors"
          >
            Generate & Download CSV
          </button>
        </div>
      </div>
    </div>
  );
};

export default FeedManager;

