import { GoogleGenAI, Type } from "@google/genai";
import { Brand, Campaign, BrandTone } from "../types";

export class GeminiService {
  // Removed static instance initialization to ensure we use the latest API key from environment
  async generateCampaignCopy(brand: Brand, campaign: Campaign) {
    if (!process.env.API_KEY) {
      return this.fallbackCopy(brand, campaign);
    }

    try {
      // Instantiate right before making an API call as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        Generate marketing copy for a campaign.
        Brand: ${brand.name} (${brand.description})
        Tone: ${brand.tone}
        Offer: ${campaign.offer}
        Objective: ${campaign.objective}

        Requirements:
        1. 15 short headlines (max 30 chars)
        2. 5 long headlines (max 90 chars)
        3. 5 short descriptions (max 60 chars)
        4. 5 long descriptions (max 90 chars)
        5. 3 Call to Action variants (max 20 chars)
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              shortHeadlines: { type: Type.ARRAY, items: { type: Type.STRING } },
              longHeadlines: { type: Type.ARRAY, items: { type: Type.STRING } },
              shortDescriptions: { type: Type.ARRAY, items: { type: Type.STRING } },
              longDescriptions: { type: Type.ARRAY, items: { type: Type.STRING } },
              ctas: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ["shortHeadlines", "longHeadlines", "shortDescriptions", "longDescriptions", "ctas"]
          }
        }
      });

      // Use .text property directly
      const result = response.text || '';
      return JSON.parse(result);
    } catch (error) {
      console.error("Gemini failed, using fallback", error);
      return this.fallbackCopy(brand, campaign);
    }
  }

  private fallbackCopy(brand: Brand, campaign: Campaign) {
    const truncate = (str: string, max: number) => 
      str.length > max ? str.substring(0, max - 3) + '...' : str;

    const baseHeadline = `${campaign.offer} at ${brand.name}`;
    const baseDesc = `Get the best deals on ${brand.industry} for our ${campaign.market} customers. ${campaign.objective === 'Sales' ? 'Shop now!' : 'Learn more.'}`;

    return {
      shortHeadlines: Array(15).fill(0).map((_, i) => truncate(`${campaign.offer} - ${brand.name} #${i + 1}`, 30)),
      longHeadlines: Array(5).fill(0).map((_, i) => truncate(`${baseHeadline}: Exclusive ${brand.tone} Collection Available Now!`, 90)),
      shortDescriptions: Array(5).fill(0).map((_, i) => truncate(`Premium ${brand.industry} products. ${campaign.offer} for a limited time.`, 60)),
      longDescriptions: Array(5).fill(0).map((_, i) => truncate(`${baseDesc} Experience the luxury of ${brand.name} with our ${brand.tone} selection.`, 90)),
      ctas: ["Shop Now", "Buy Now", "Claim Offer"]
    };
  }
}

export const geminiService = new GeminiService();

import React, { useEffect, useRef, useState } from 'react';
import { useApp } from '../App';
// Import fabric to resolve "Cannot find name 'fabric'" errors
import { fabric } from 'fabric';

interface EditorProps {
  assetId: string;
  onClose: () => void;
}

const Editor: React.FC<EditorProps> = ({ assetId, onClose }) => {
  const { campaigns, updateCampaign } = useApp();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fabricCanvas = useRef<any>(null);
  const [activeObject, setActiveObject] = useState<any>(null);

  const campaign = campaigns.find(c => c.assets.some(a => a.id === assetId));
  const asset = campaign?.assets.find(a => a.id === assetId);

  useEffect(() => {
    if (!canvasRef.current || !asset) return;

    // Initialize fabric canvas
    fabricCanvas.current = new fabric.Canvas(canvasRef.current, {
      backgroundColor: '#ffffff',
      width: asset.size.width > 800 ? 800 : asset.size.width,
      height: (asset.size.width > 800 ? 800 : asset.size.width) * (asset.size.height / asset.size.width),
    });

    // Zoom and fit based on asset dimensions
    const zoom = fabricCanvas.current.width / asset.size.width;
    fabricCanvas.current.setZoom(zoom);

    // Load state if exists or add initial elements
    if (asset.editorState) {
      fabricCanvas.current.loadFromJSON(asset.editorState);
    } else {
      // Add background rectangle
      const rect = new fabric.Rect({
        left: 0, top: 0,
        fill: '#f8fafc',
        width: asset.size.width, height: asset.size.height,
        selectable: false
      });
      fabricCanvas.current.add(rect);

      // Add promotional text
      const text = new fabric.IText(campaign?.offer || 'Your Offer', {
        left: 100, top: 100,
        fontSize: 120,
        fontFamily: 'Inter',
        fontWeight: 'bold',
        fill: '#000000'
      });
      fabricCanvas.current.add(text);

      // Add call to action button
      const btn = new fabric.Rect({
        left: 100, top: 300,
        fill: '#000000',
        width: 400, height: 100,
        rx: 10, ry: 10
      });
      const btnText = new fabric.Text(campaign?.cta || 'Shop Now', {
        left: 150, top: 325,
        fill: '#ffffff',
        fontSize: 40,
        fontFamily: 'Inter'
      });
      fabricCanvas.current.add(new fabric.Group([btn, btnText], { left: 100, top: 400 }));
    }

    fabricCanvas.current.on('selection:created', (e: any) => setActiveObject(e.selected[0]));
    fabricCanvas.current.on('selection:updated', (e: any) => setActiveObject(e.selected[0]));
    fabricCanvas.current.on('selection:cleared', () => setActiveObject(null));

    return () => {
      fabricCanvas.current?.dispose();
    };
  }, [assetId, asset, campaign?.cta, campaign?.offer]);

  const handleSave = () => {
    if (!campaign || !asset || !fabricCanvas.current) return;

    const newState = JSON.stringify(fabricCanvas.current.toJSON());
    const dataUrl = fabricCanvas.current.toDataURL({ format: 'png', multiplier: 1 / fabricCanvas.current.getZoom() });

    const updatedAssets = campaign.assets.map(a => 
      a.id === assetId ? { ...a, editorState: newState, dataUrl } : a
    );

    updateCampaign({ ...campaign, assets: updatedAssets });
    onClose();
  };

  const addText = () => {
    const text = new fabric.IText('Double click to edit', {
      left: 100, top: 100,
      fontSize: 60,
      fontFamily: 'Inter'
    });
    fabricCanvas.current.add(text);
    fabricCanvas.current.setActiveObject(text);
  };

  const changeColor = (color: string) => {
    if (activeObject) {
      activeObject.set('fill', color);
      fabricCanvas.current.renderAll();
    }
  };

  if (!asset) return null;

  return (
    <div className="fixed inset-0 bg-slate-900 z-[60] flex flex-col">
      <nav className="h-16 border-b border-slate-700 bg-slate-800 flex items-center justify-between px-6 text-white">
        <div className="flex items-center gap-4">
          <button onClick={onClose} className="hover:text-slate-300">✕</button>
          <h2 className="font-bold text-sm uppercase tracking-widest">{asset.name} ({asset.size.width}x{asset.size.height})</h2>
        </div>
        <button 
          onClick={handleSave}
          className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-lg font-bold text-sm transition-colors"
        >
          Save Edits
        </button>
      </nav>

      <div className="flex-1 flex overflow-hidden">
        {/* Toolbar */}
        <aside className="w-20 bg-slate-800 border-r border-slate-700 flex flex-col items-center py-6 gap-6 text-white text-xs">
          <button onClick={addText} className="flex flex-col items-center gap-1 hover:bg-slate-700 p-2 rounded w-full">
            <span>T</span>
            Text
          </button>
          <button onClick={() => {
            const rect = new fabric.Rect({ width: 200, height: 200, fill: '#000', left: 100, top: 100 });
            fabricCanvas.current.add(rect);
          }} className="flex flex-col items-center gap-1 hover:bg-slate-700 p-2 rounded w-full">
            <span>⬜</span>
            Shape
          </button>
        </aside>

        {/* Workspace */}
        <div className="flex-1 bg-slate-900 flex items-center justify-center p-12 overflow-auto">
          <div className="bg-white shadow-2xl relative">
            <canvas ref={canvasRef} />
          </div>
        </div>

        {/* Inspector */}
        <aside className="w-64 bg-slate-800 border-l border-slate-700 p-6 text-white">
          <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-6">Inspector</h3>
          {activeObject ? (
            <div className="space-y-6">
              <div>
                <label className="block text-[10px] text-slate-500 mb-2 uppercase font-bold">Fill Color</label>
                <div className="grid grid-cols-4 gap-2">
                  {['#000000', '#ffffff', '#ff0000', '#00ff00', '#0000ff', '#ffff00', '#d4af37', '#7c3aed'].map(c => (
                    <button 
                      key={c}
                      onClick={() => changeColor(c)}
                      className="w-8 h-8 rounded border border-slate-600"
                      style={{ backgroundColor: c }}
                    />
                  ))}
                </div>
              </div>
              {activeObject.text !== undefined && (
                <div>
                  <label className="block text-[10px] text-slate-500 mb-2 uppercase font-bold">Font Size</label>
                  <input 
                    type="range" min="10" max="500" 
                    value={activeObject.fontSize} 
                    onChange={(e) => {
                      activeObject.set('fontSize', parseInt(e.target.value));
                      fabricCanvas.current.renderAll();
                    }}
                    className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                  />
                </div>
              )}
              <button 
                onClick={() => {
                  fabricCanvas.current.remove(activeObject);
                  fabricCanvas.current.discardActiveObject();
                }}
                className="w-full py-2 bg-red-900/30 text-red-400 rounded-lg text-xs font-bold border border-red-900/50"
              >
                Delete Layer
              </button>
            </div>
          ) : (
            <p className="text-slate-500 text-xs italic">Select an element to edit properties.</p>
          )}
        </aside>
      </div>
    </div>
  );
};

